import datetime

holidays = {datetime.date(2026,10,12)}

def is_business_day(d):
    return d.weekday() < 5 and d not in holidays

def add_business_days(start, n, first_is_start=True):
    # returns the date of the nth business day counting start (if business day) as day 1
    d = start
    count = 0
    while True:
        if is_business_day(d):
            count += 1
            if count == n:
                return d
        d += datetime.timedelta(days=1)

def next_business_day(d):
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d):
        d += datetime.timedelta(days=1)
    return d

start = datetime.date(2026,10,5)
print('start weekday', start.strftime('%A'))

phases = [('Discovery',3), ('Build',6), ('QA',4), ('Release',1)]
cur_start = start
for name, dur in phases:
    end = add_business_days(cur_start, dur)
    print(name, 'start', cur_start, cur_start.strftime('%a'), 'end', end, end.strftime('%a'))
    cur_start = next_business_day(end)
